/**
 * DTOs matching contracts/openapi.yaml schemas.
 * All identifiers use pseudonyms (emp_*, prj_*, etc.) — no personal data.
 * Generated by hand from the contract; replace with openapi-typescript when ready.
 */

// ──── primitives ────

export type WeekKey = string; // ^[0-9]{4}-W(0[1-9]|[1-4][0-9]|5[0-3])$
export type Grade = 'J' | 'M' | 'S' | 'L' | 'P';
export type Level = 1 | 2 | 3 | 4 | 5;

// ──── pagination ────

export interface PageMeta {
  limit: number;
  offset: number;
  total: number;
}

// ──── taxonomy ────

export type RoleFamily =
  | 'engineering'
  | 'quality'
  | 'data'
  | 'infrastructure'
  | 'product'
  | 'analysis'
  | 'design'
  | 'management'
  | 'security';

export type CompetencyCategory =
  | 'language'
  | 'framework'
  | 'database'
  | 'messaging'
  | 'cloud'
  | 'devops'
  | 'testing'
  | 'analytics'
  | 'ml'
  | 'architecture'
  | 'security'
  | 'process'
  | 'domain'
  | 'soft_skill';

export interface Role {
  role_id: string;
  name_en: string;
  name_ru: string;
  family: RoleFamily;
  synonyms: string[];
  core_competencies: string[];
  typical_grades: Grade[];
}

export interface Competency {
  competency_id: string;
  name_en: string;
  name_ru: string;
  category: CompetencyCategory;
  synonyms: string[];
  roles: string[];
  level_scale: 5;
}

// ──── reference ────

export interface GradeBand {
  grade: Grade;
  label_ru: string;
  cost_coefficient: number;
  typical_level_range: [Level, Level];
}

export interface Weights {
  M1: number;
  M2: number;
  M3: number;
  M4?: number;
  M5: number;
  M6: number;
  M7: number;
  M8: number;
  M9: number;
  M10: number;
  M11: number;
  M12: number;
}

export type PresetName = 'fast' | 'economical' | 'balanced' | 'low_risk';

export interface WeightPreset {
  preset: PresetName;
  label_ru: string;
  description_ru: string;
  weights: Weights;
  sum_check: number;
}

export interface PlanningParams {
  time_model: {
    week_start: 'monday';
    working_days_per_week: 5;
    hours_per_day: 8;
    weekly_hours_norm: 40;
    reserve_ratio: number;
    calendar: string;
  };
  schedule: {
    monte_carlo_runs: number;
    monte_carlo_seed: number;
    portfolio_tau_working_days: number;
  };
  solver: {
    default_time_limit_ms: number;
    recalc_time_limit_ms: number;
    k_min: number;
    k_max: number;
    min_jaccard_diversity: number;
  };
  limits: {
    max_employees: number;
    max_requirements: number;
  };
  metrics_version: string;
}

// ──── employees ────

export type EmploymentType = 'internal' | 'contractor' | 'external_partner';

export interface CapacityProfile {
  weekly_hours_norm: number;
  reserve_ratio: number;
  max_utilization_ratio: number;
}

export interface Employee {
  display_name?: string;
  employee_id: string;
  grade: Grade;
  role_profile_id: string;
  unit_id: string;
  employment_type: EmploymentType;
  bench_flag: boolean;
  capacity_profile: CapacityProfile;
  cost_coefficient: number;
  active: boolean;
}

export type CompetencySource =
  | 'self_assessment'
  | 'manager_review'
  | 'project_history'
  | 'certification'
  | 'hr_import';

export interface EmployeeCompetency {
  competency_id: string;
  level: Level;
  confidence: number;
  last_used?: string;
  source: CompetencySource;
}

export interface CapacityWeek {
  employee_id: string;
  week: WeekKey;
  working_days: number;
  norm_hours: number;
  reserved_hours: number;
  assigned_hours: number;
  absence_hours: number;
  free_hours: number;
  load_ratio: number;
  unavailable: boolean;
}

export type BriefStatus = 'uploaded' | 'extracting' | 'extracted' | 'needs_review' | 'confirmed' | 'failed';
export interface Brief { 
  brief_id: string; 
  title: string; 
  source_type: 'text' | 'docx' | 'pdf' | 'txt'; 
  language: 'ru' | 'en'; 
  status: BriefStatus; 
  created_at: string; 
  requirement_count: number; 
  needs_review_count: number; 
  reason_codes: ReasonCode[];
  requested_start_week?: WeekKey;
  deadline_week?: WeekKey;
}
export interface Evidence { kind: string; quote: string; char_start?: number; char_end?: number; }
export interface Requirement { requirement_id: string; brief_id: string; role: { role_id: string; name_ru: string; confidence: number }; competency_id: string; competency_name_ru: string; level: Level; criticality: 'must' | 'should' | 'nice'; headcount: number; confidence: number; needs_review: boolean; effort: { min_person_days: number; likely_person_days: number; max_person_days: number; unit: 'person_days' }; assumptions: string[]; evidence: Evidence[]; }

// ──── errors (RFC 9457 shape, contracts/openapi.yaml#Problem) ────

export interface FieldError {
  field: string;
  code: string;
  detail: string;
}

export interface Problem {
  type: string;
  title: string;
  status: number;
  code: string;
  detail: string;
  request_id: string;
  retryable?: boolean;
  reason_codes: ReasonCode[];
  errors?: FieldError[];
}

